@@ -1057,3 +1057,5 @@
-    // Select a 128-byte register group for MaxVectorSize <= 128; otherwise use m1.
-    // Integer LMUL encodes log2(multiplier): m1/m2/m4/m8 = 0/1/2/3.
-    const int lmul_multiplier = 128 / MIN2((int)MaxVectorSize, 128);
+    // 128 is the target vector register group size in bytes, not a fixed copy size.
+    // Benchmarks on one 256-bit VLEN system favored m4 over m8; use m1 when a
+    // single register is already wider than the target.
+    const int vector_length = static_cast<int>(VM_Version::initial_vector_length());
+    const int lmul_multiplier = MAX2(128 / vector_length, 1);
